# Build with correct transformations
def make_final_tiled(grid):
    Q0 = grid
    Q1 = rotate_90_fixed(grid)
    Q2 = rotate_270_fixed(grid)
    Q3 = rotate_180_fixed(grid)

    output = []
    for r in range(len(grid)):
        output.append(Q0[r] + Q1[r])
        output.append(Q2[r] + Q3[r])
    return output

